css:
body.theme-default{--k-accent:#1f5eff;--k-accent-dark:#1c232c;--k-soft:#dfe6f2;--k-ink:#1c232c;--k-muted:#5d6876;--k-line:#b5bec9;--k-bg:#e7ebf0;--k-warn:#ff6a3d;
 --chart-1:#1f5eff;--chart-2:#1c232c;--chart-3:#ff6a3d;--chart-4:#7f9cf5;--chart-5:#ff6a3d;--chart-6:#9aa5b3;--chart-ink:#1c232c;--chart-muted:#5d6876;--chart-grid:#cfd6df;
 font-family:"Malgun Gothic","Apple SD Gothic Neo","Noto Sans KR",sans-serif}
.num,.claim-big,.vs-num,.seg-amt,.roas,.pair-nums,.targets span{font-family:"Bahnschrift","DIN Alternate","Avenir Next Condensed","Malgun Gothic",sans-serif;font-variant-numeric:tabular-nums;letter-spacing:0}
#stage.composed-scene{background:#e7ebf0}
.composed-scene .deck-top{color:#5d6876}
.composed-scene .deck-mark i{background:#ff6a3d;border-radius:2px}
.composed-scene .eyebrow{color:#5d6876;font-weight:600;font-size:17px;letter-spacing:0}
.composed-scene .scene-title{font-size:46px;font-weight:700;letter-spacing:-.025em;color:#1c232c;max-width:1240px}
.composed-scene .scene-bottom{border-top:2px solid #1c232c;padding-top:12px}
.composed-scene .message{font-size:19px;font-weight:600}
.composed-scene .message-label{background:transparent;color:#ff6a3d;padding:0;margin-right:14px;font-size:17px}
.reveal-spotlight [data-step].focus{box-shadow:none;outline:none}
.reveal-spotlight [data-step].dim{opacity:.28;filter:grayscale(1)}
.note{font-size:14px;color:#5d6876;margin:6px 0 0}
.verdict{font-weight:700;color:#1c232c;border-left:4px solid #ff6a3d;padding-left:12px}
.heat-ink{color:#ff6a3d}
.open-hero{display:grid;grid-template-columns:330px 1fr;gap:56px;flex:1;min-height:0;align-items:stretch}
.gauge{margin:0;display:flex;flex-direction:column;min-height:0}
.gauge svg{flex:1;min-height:0;width:100%}
.gauge figcaption{font-size:13px;color:#5d6876}
.gauge-label{font-size:19px;font-weight:700;fill:#1c232c;font-family:"Bahnschrift","Malgun Gothic",sans-serif}
.gauge-label.heat{fill:#ff6a3d}
.tumbler{overflow:visible}
.claims{display:flex;flex-direction:column;justify-content:center;gap:26px;max-width:820px}
.claim{border-left:3px solid #b5bec9;padding:2px 0 2px 22px}
.claim.focus{border-left-color:#1f5eff}
.claim-kicker{margin:0 0 4px;font-size:15px;font-weight:700;color:#1f5eff}
.claim p{margin:0;font-size:20px;line-height:1.55;color:#1c232c}
.claim-big{font-size:96px!important;font-weight:600;line-height:1!important;color:#1c232c!important;margin:2px 0 8px!important}
.claim-big span{font-size:44px;color:#5d6876}
.claim.ask p{font-weight:600}
.claim button[data-goto]{margin-top:12px}
button[data-goto]{border-color:#1c232c;color:#1c232c;border-radius:4px}
button[data-goto]::before{content:none}
button[data-goto]:hover{background:#1c232c;color:#fff}
.stack-gap{display:flex;flex-direction:column;gap:30px;flex:1;min-height:0}
.versus{display:grid;gap:14px}
.vs-row{display:grid;grid-template-columns:70px 1fr 120px;align-items:center;gap:18px}
.vs-name{font-size:19px;font-weight:700}
.vs-track{height:38px;background:#d5dce6}
.vs-bar{display:block;height:100%;background:#1c232c;position:relative}
.vs-bar.cold{background:#1f5eff}
.vs-over{position:absolute;right:0;top:0;height:100%;background:#ff6a3d}
.vs-num{font-size:34px;font-weight:600;text-align:right}
.two-col{display:grid;grid-template-columns:1fr 1fr;gap:64px}
.two-col h3{font-size:23px;margin:0 0 10px}
.two-col p{font-size:18px;line-height:1.6;margin:0 0 10px;max-width:640px}
.big-line{font-size:40px!important;font-weight:600;margin:0 0 8px!important}
.journey{display:flex;flex-direction:column;gap:12px;flex:1;justify-content:center}
.journey-bar{display:flex;height:120px;gap:4px}
.seg{position:relative;background:#1f5eff;display:flex;align-items:flex-end;padding:12px 14px}
.seg:nth-child(2){background:#4d80ff}.seg:nth-child(3){background:#1c232c}.seg:nth-child(4){background:#ff6a3d}
.seg-amt{color:#fff;font-size:30px;font-weight:600}
.journey-roles{display:grid;grid-template-columns:repeat(4,1fr);gap:28px;margin-top:22px}
.role{display:flex;flex-direction:column;gap:6px;padding-top:12px;border-top:6px solid #1f5eff;min-width:0}
.role-1{border-top-color:#4d80ff}.role-2{border-top-color:#1c232c}.role-3{border-top-color:#ff6a3d}
.role em{font-style:normal;color:#5d6876;font-weight:600;margin-left:6px}
.role b{font-size:28px}
.role span{font-size:18px;font-weight:700;color:#1f5eff}
.role small{font-size:15px;color:#5d6876;line-height:1.45}
.pairs-wrap{display:flex;flex-direction:column;gap:14px;flex:1;min-height:0}
.legend{display:flex;gap:22px;align-items:center;font-size:15px}
.legend i{display:inline-block;width:14px;height:14px;margin-right:6px;vertical-align:-2px}
i.spend{background:#9aa5b3}i.rev{background:#1f5eff}
.pairs{display:grid;gap:34px;margin-top:18px}
.pair{display:grid;grid-template-columns:150px 1fr 230px 170px;align-items:center;gap:20px}
.pair-name{font-size:21px;font-weight:700}
.bars{display:grid;gap:5px}
.bars i{display:block;height:30px}
.pair-nums{font-size:21px;color:#5d6876;text-align:right}
.roas{font-size:30px;font-weight:600;text-align:right}
.pair.best .rev{background:#ff6a3d}.pair.best .roas{color:#ff6a3d}
.pair.low .roas{color:#5d6876}
.aside-row{display:flex;gap:28px;align-items:center;margin-top:auto;font-size:17px;max-width:1300px}
.aside-row p{margin:0}
.funnel-scene{display:flex;flex-direction:column;gap:18px;flex:1;min-height:0}
.stages{display:grid;grid-template-columns:repeat(5,1fr);margin:0;padding:0;list-style:none;counter-reset:s;border-top:2px solid #1c232c}
.stages li{padding:12px 16px 0 0;display:flex;flex-direction:column}
.stages b{font-size:34px;font-weight:600}
.stages span{font-size:15px;color:#5d6876}
.stages li.hot b{color:#ff6a3d}
.funnel-split{display:grid;grid-template-columns:1.5fr 1fr;gap:48px;flex:1;min-height:0}
.funnel-chart{min-height:0}
.next-task{align-self:center}
.next-task h3{font-size:26px;margin:0 0 12px}
.next-task p{font-size:18px;line-height:1.6;margin:0 0 12px}
.trend-scene{display:grid;grid-template-columns:1fr 360px;gap:48px;flex:1;min-height:0}
.trend-chart{min-height:0}
.margin-notes{display:flex;flex-direction:column;justify-content:center;gap:28px}
.margin-notes p{margin:0;font-size:18px;line-height:1.55;border-left:3px solid #ff6a3d;padding-left:16px}
.margin-notes b{display:block;font-size:30px;font-weight:600;margin-bottom:4px}
.decision{display:grid;grid-template-columns:420px 1fr;grid-template-rows:1fr auto;gap:28px 64px;flex:1;min-height:0}
.targets{display:flex;flex-direction:column;justify-content:center;gap:18px;grid-row:span 2}
.targets p{margin:0;font-size:30px;font-weight:600;color:#5d6876}
.targets span{font-size:120px;line-height:.95;color:#1f5eff;margin-right:6px}
.targets small{display:block;font-size:16px;font-weight:600;color:#1c232c;margin-top:2px}
.actions{margin:0;padding:0;list-style:none;display:flex;flex-direction:column;justify-content:center;gap:20px;counter-reset:a}
.actions li{counter-increment:a;display:grid;grid-template-columns:44px 1fr;column-gap:16px;align-items:baseline}
.actions li::before{content:counter(a);grid-row:span 2;font-family:"Bahnschrift","Malgun Gothic",sans-serif;font-size:34px;color:#ff6a3d}
.actions b{font-size:25px}
.actions span{font-size:18px;color:#5d6876}
.ask-line{margin:0;font-size:26px;font-weight:700;background:#1c232c;color:#fff;padding:18px 24px}
.check{width:100%;border-collapse:collapse;font-size:18px}
.check th{text-align:left;border-bottom:2px solid #1c232c;padding:10px 12px}
.check td{border-bottom:1px solid #b5bec9;padding:12px}
.check tr.flag td{color:#ff6a3d;font-weight:600}
@media (prefers-reduced-motion: reduce){.tumbler .fill{transition:none}}
